#include <bits/stdc++.h>
using namespace std;struct DSU{vector<int>p,d;DSU(int n):p(n+1),d(n+1,0){iota(p.begin(),p.end(),0);}int find(int x){if(p[x]==x)return x;int y=p[x],r=find(y);d[x]=(d[x]+d[y])%3;return p[x]=r;}bool add(int typ,int x,int y){int rx=find(x),ry=find(y),rel=(typ==1?0:1);if(rx==ry)return (d[x]-d[y]+3)%3==rel; p[rx]=ry;d[rx]=(rel+d[y]-d[x]+3)%3;return true;}};int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n,k;if(!(cin>>n>>k))return 0;DSU u(n);int bad=0;for(int i=0,D,x,y;i<k;i++){cin>>D>>x>>y;if(x<1||x>n||y<1||y>n|| (D==2&&x==y) || (D!=1&&D!=2)){bad++;continue;}if(!u.add(D,x,y))bad++;}cout<<bad<<endl;return 0;}